cards.content:
{% from 'planes.jinja' import plane_pick, plane_art, plane_where, plane_trend, plane_flight, plane_route, plane_model, plane_alt, plane_mph, plane_extra %}
{% set id = plane_pick('') | trim %}{% set f = (state_attr('sensor.flightradar24_current_in_area', 'flights') or []) | selectattr('id', 'eq', id) | first if id else none %}{% set x = plane_extra(f) | from_json if f else {} %}
{% if f %}
#### ✈︎ OVERHEAD NOW <span>{{ plane_where(f) }} · {{ plane_trend(f) }}</span>

<a href="#plane"><img src="{{ plane_art(f) }}"></a>

# {{ plane_flight(f) }}
{% if x.get('poi') %}### ★ {{ x.get('notable_name') }} <span>{{ x.get('notable_category') }}</span>{% endif %}
{{ plane_route(f) }}{% if x.get('owner') and not f.airline %}<br>Owned by {{ x.get('owner') }}{% endif %}

- **{{ plane_alt(f) }}** ft
- **{{ plane_mph(f) }}** mph
- **{{ plane_model(f) }}** {{ f.aircraft_registration or x.get('registration') or 'type' }}
{% endif %}

style.ha-markdown$:
ha-markdown-element { display: block; }
h4 { display: flex; justify-content: space-between; margin: 0; font-size: 15px; font-weight: 600; letter-spacing: .3px; color: var(--primary-color); }
h4 span { color: var(--secondary-text-color); font-weight: 500; }
a { display: block; -webkit-tap-highlight-color: transparent; }
img { display: block; width: 100%; margin: 8px 0 4px; filter: drop-shadow(0 10px 12px rgba(20, 30, 60, .22)); }
h1 { margin: 0; font-size: 28px; font-weight: 700; line-height: 1.15; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
p { margin: 2px 0 0; font-size: 17px; color: var(--secondary-text-color); }
h3 { margin: 4px 0 0; font-size: 18px; font-weight: 700; color: var(--accent-color); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
h3 span { font-size: 13px; font-weight: 500; color: var(--secondary-text-color); }
ul { display: flex; flex-wrap: wrap; gap: 8px; margin: 14px 0 2px !important; padding: 0 !important; list-style: none; }
li { display: flex; flex-direction: column; align-items: center; min-width: 64px; padding: 7px 16px 6px; border-radius: 14px;
  background: color-mix(in srgb, var(--primary-text-color) 8%, transparent); border: 1px solid color-mix(in srgb, var(--primary-text-color) 12%, transparent);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); font-size: 12px; line-height: 1.35; letter-spacing: .3px; color: var(--secondary-text-color); }
li strong { font-size: 17px; font-weight: 700; letter-spacing: 0; color: var(--primary-text-color); }

cards.content:
{% from 'planes.jinja' import plane_pick, plane_art, plane_where, plane_trend, plane_flight, plane_route, plane_model, plane_alt, plane_mph, plane_extra %}
{% set id = plane_pick(states('input_text.plane_takeover_id')) | trim %}{% set f = (state_attr('sensor.flightradar24_current_in_area', 'flights') or []) | selectattr('id', 'eq', id) | first if id else none %}{% set x = plane_extra(f) | from_json if f else {} %}
{% if f %}
{% set lat = state_attr('zone.home', 'latitude') | float(0) %}{% set lon = state_attr('zone.home', 'longitude') | float(0) %}
##### OVERHEAD
### {{ plane_where(f) }} · {{ plane_trend(f) }}

<img src="{{ plane_art(f) }}">

## {{ ('★ ' ~ x.get('notable_name')) if x.get('poi') else (f.airline or 'Private') }} · {{ f.aircraft_model or f.aircraft_code }}
{{ [f.flight_number, plane_route(f), f.aircraft_registration or x.get('registration'), ('Owned by ' ~ x.get('owner')) if (x.get('owner') and not f.airline) else '', plane_alt(f) ~ ' ft'] | select | join(' · ') }}

###### No {{ states('counter.planes_today') }} today · {{ now().strftime('%A %-d %B %Y') }} · {{ '%.2f' | format(lat | abs) }}° {{ 'N' if lat >= 0 else 'S' }} {{ '%.2f' | format(lon | abs) }}° {{ 'W' if lon < 0 else 'E' }} · Wheat Ridge, Colorado
{% endif %}

ha-card { position: fixed !important; inset: 0 !important; z-index: 1000; margin: 0; padding: 0 !important;
  border: 0 !important; border-radius: 0 !important; box-shadow: none !important;
  backdrop-filter: none !important; -webkit-backdrop-filter: none !important;
  background: #8d0e12 !important; color: #f3e6c8; font-family: Georgia, 'Times New Roman', serif; }

style.ha-markdown$:
ha-markdown-element { position: absolute; inset: 0; }
h5 { position: absolute; left: 5vw; top: 6.5vh; margin: 0; font-size: 15px; font-weight: 400; letter-spacing: 5px; }
h3 { position: absolute; right: 5vw; top: 6.5vh; margin: 0; font-size: 13px; font-weight: 400; letter-spacing: 3px; text-transform: uppercase; opacity: .8; }
img { position: absolute; left: 5.5vw; top: 20vh; width: 89vw; height: 50vh; object-fit: contain; object-position: center bottom; filter: drop-shadow(0 18px 18px rgba(0, 0, 0, .25)); }
h2 { position: absolute; left: 9.4vw; top: 73.5vh; margin: 0; font-size: 30px; font-weight: 400; }
p { position: absolute; left: 9.4vw; top: 79.5vh; margin: 0; font-size: 19px; opacity: .85; }
h6 { position: absolute; left: 5vw; right: 5vw; bottom: 5.5vh; margin: 0; text-align: center; font-family: 'Segoe UI', Roboto, sans-serif; font-size: 11px; font-weight: 400; letter-spacing: 2.4px; text-transform: uppercase; opacity: .7; }

